ControlPropertyState.AutoRuleBindingString:
Set(varBatchTotal, CountRows(colSpSelected));
Set(varProcessedCount, 0);
ClearCollect(
    colHomeQueue,
    ForAll(
        colSpSelected As selectedFile,
        {
            id: Text(GUID()),
            name: Text(selectedFile.name),
            source: "sharepoint",
            image: selectedFile.image,
            path: With(
                { rawPath: Text(selectedFile.path) },
                If(Left(rawPath, 1) = "/", rawPath, "/" & rawPath)
            ),
            file_url: With(
                { rawPath: Text(selectedFile.path) },
                If(
                    !IsBlank(rawPath),
                    Substitute(
                        If(Left(rawPath, 1) = "/", rawPath, "/" & rawPath),
                        " ",
                        "%20"
                    ),
                    Text(selectedFile.file_url)
                )
            ),
            folder: Text(selectedFile.folder),
            processed: false
        }
    )
);
With(
    { nextItem: First(colHomeQueue) },
    Set(varHomeSelectedId, nextItem.id);
    Set(varImage, Coalesce(nextItem.image, SampleImage));
    Set(varImageUrl, "");
    Set(varImageName, If(!IsBlank(nextItem.path), "SPPATH|" & nextItem.path, Coalesce(nextItem.name, "label.jpg")))
);
ClearCollect(varCandidates, []);
ClearCollect(colSelected, []);
ClearCollect(colSpSelected, []);
ClearCollect(colSpFolderFiles, []);
Set(varSpFolderName, "");
Set(varSpFolderPath, "");
Set(varSpPickedFolder, "");
Set(varError, "");
Navigate(srcHome, ScreenTransition.None)

If(
    IfError(Value(ThisItem.FileSizeBytes), 0) > 4 * 1024 * 1024,
    false,
    With(
        {
            selectedName: Coalesce(
                Text(ThisItem.'{FilenameWithExtension}'),
                Text(ThisItem.'{Name}')
            ),
            selectedPath: If(
                Right(Text(ThisItem.'{Path}'), 1) = "/",
                Text(ThisItem.'{Path}') & Coalesce(
                    Text(ThisItem.'{FilenameWithExtension}'),
                    Text(ThisItem.'{Name}')
                ),
                Text(ThisItem.'{Path}') & "/" & Coalesce(
                    Text(ThisItem.'{FilenameWithExtension}'),
                    Text(ThisItem.'{Name}')
                )
            ),
            selectedUrl: Coalesce(Text(ThisItem.'{Link}'), Substitute(Text(ThisItem.'{FullPath}'), " ", "%20")),
            selectedThumb: IfError(ThisItem.'{Thumbnail}'.Large, SampleImage)
        },
        If(
            CountRows(Filter(colSpSelected As selectedRow, selectedRow.path = selectedPath)) > 0,
            RemoveIf(colSpSelected, ThisRecord.path = selectedPath),
            Collect(
                colSpSelected,
                {
                    name: selectedName,
                    path: selectedPath,
                    file_url: selectedUrl,
                    image: selectedThumb,
                    folder: varSpFolderName
                }
            )
        )
    )
)
